import sys


def edit_distance(a: str, b: str) -> int:
    """Levenshtein 距离：插入 / 删除 / 替换代价均为 1，滚动数组实现。"""
    if not a:
        return len(b)
    if not b:
        return len(a)
    if len(a) < len(b):
        a, b = b, a
    m = len(b)
    prev = list(range(m + 1))
    for i in range(1, len(a) + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            cur[j] = min(
                prev[j] + 1,
                cur[j - 1] + 1,
                prev[j - 1] + cost,
            )
        prev = cur
    return prev[m]


def main() -> None:
    lines = sys.stdin.read().splitlines()
    a = lines[0].strip() if len(lines) >= 1 else ""
    b = lines[1].strip() if len(lines) >= 2 else ""
    print(edit_distance(a, b))


if __name__ == "__main__":
    main()
